-- Azure SQL Database / SQL Server. Run in target database.
CREATE TABLE dbo.Segments (SegmentCode varchar(12) NOT NULL PRIMARY KEY, SegmentName nvarchar(80) NOT NULL UNIQUE);
CREATE TABLE dbo.Employees (EmployeeCode varchar(12) NOT NULL PRIMARY KEY, FirstName nvarchar(100) NOT NULL, LastName nvarchar(100) NOT NULL, StartDate date NOT NULL, EndDate date NULL, CONSTRAINT CK_EmployeeDates CHECK (EndDate IS NULL OR EndDate >= StartDate));
CREATE TABLE dbo.Portfolios (PortfolioCode char(6) NOT NULL PRIMARY KEY, BranchId int NOT NULL, EmployeeCode varchar(12) NULL REFERENCES dbo.Employees(EmployeeCode), StartDate date NOT NULL, EndDate date NULL, CONSTRAINT CK_PortfolioDates CHECK (EndDate IS NULL OR EndDate >= StartDate));
CREATE TABLE dbo.Customers (CustomerCode bigint NOT NULL PRIMARY KEY, FirstName nvarchar(100) NOT NULL, LastName nvarchar(100) NOT NULL, SegmentCode varchar(12) NOT NULL REFERENCES dbo.Segments(SegmentCode));
CREATE TABLE dbo.Products (ProductCode varchar(20) NOT NULL PRIMARY KEY, ProductName nvarchar(150) NOT NULL, Multiplier smallint NOT NULL CONSTRAINT CK_ProductMultiplier CHECK (Multiplier IN (-1,1)));
CREATE TABLE dbo.SubProducts (ProductCode varchar(20) NOT NULL REFERENCES dbo.Products(ProductCode), SubProductCode varchar(20) NOT NULL, SubProductName nvarchar(150) NOT NULL, Multiplier smallint NOT NULL CONSTRAINT CK_SubProductMultiplier CHECK (Multiplier IN (-1,1)), CONSTRAINT PK_SubProducts PRIMARY KEY(ProductCode,SubProductCode));
CREATE TABLE dbo.ProductSegments (ProductCode varchar(20) NOT NULL REFERENCES dbo.Products(ProductCode), SegmentCode varchar(12) NOT NULL REFERENCES dbo.Segments(SegmentCode), CONSTRAINT PK_ProductSegments PRIMARY KEY(ProductCode,SegmentCode));
CREATE TABLE dbo.Transactions (TransactionId bigint IDENTITY(1,1) NOT NULL PRIMARY KEY, BranchId int NOT NULL, TransactionCode varchar(30) NOT NULL, PortfolioCode char(6) NOT NULL REFERENCES dbo.Portfolios(PortfolioCode), CustomerCode bigint NOT NULL REFERENCES dbo.Customers(CustomerCode), ProductCode varchar(20) NOT NULL, SubProductCode varchar(20) NOT NULL, TransactionDate date NOT NULL, YPProfit decimal(19,4) NOT NULL, TLProfit decimal(19,4) NOT NULL, CurrencyCode char(3) NOT NULL, CONSTRAINT FK_Transactions_SubProduct FOREIGN KEY(ProductCode,SubProductCode) REFERENCES dbo.SubProducts(ProductCode,SubProductCode));
CREATE INDEX IX_Transactions_Month ON dbo.Transactions(TransactionDate) INCLUDE (PortfolioCode,CustomerCode,ProductCode,SubProductCode,BranchId,YPProfit,TLProfit,CurrencyCode);
CREATE TABLE dbo.TransactionExceptions (TransactionId bigint NOT NULL PRIMARY KEY REFERENCES dbo.Transactions(TransactionId), OverrideYPProfit decimal(19,4) NOT NULL, OverrideTLProfit decimal(19,4) NOT NULL, Reason nvarchar(500) NOT NULL, UpdatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.MonthlyProfitability (DateKey int NOT NULL, PortfolioCode char(6) NOT NULL, BranchId int NOT NULL, CustomerCode bigint NOT NULL, SegmentCode varchar(12) NOT NULL, ProductCode varchar(20) NOT NULL, SubProductCode varchar(20) NOT NULL, CurrencyCode char(3) NOT NULL, TotalYPProfit decimal(28,4) NOT NULL, TotalTLProfit decimal(28,4) NOT NULL, TransactionCount int NOT NULL, CONSTRAINT PK_MonthlyProfitability PRIMARY KEY(DateKey,PortfolioCode,BranchId,CustomerCode,SegmentCode,ProductCode,SubProductCode,CurrencyCode));
